import React, { useState, useRef, useEffect } from "react";
import { useDispatch } from 'react-redux'
import { setIsBonusModal } from '../store/reducers/modal';

import music_off from '../assets/img/temp/music_off.png';
import music_on from '../assets/img/temp/music_on.png';
import favorites from '../assets/img/temp/favorites.png';
import gear_normal from '../assets/img/temp/gear_normal.png';
import myjp_icon from '../assets/img/temp/myjp_icon.png';
import jackpotSound from '../assets/sounds/myjackpot/intro.default.mp3';
import bgmusic from '../assets/sounds/common/bgmusic.mp3';
import dailyBox from '../assets/img/themes/dailybox.png';
import goldbonusbg from '../assets/img/win/goldbonusbg.png';
import goldbonustitle from '../assets/img/win/goldbonustitle.png';

const IconMenu = () => {
    const dispatch = useDispatch();
    const [isMusicOn, setIsMusicOn] = useState(false);
    const audioRef = useRef(null);
    const [windowSize, setWindowSize] = useState({
        width: window.innerWidth,
        height: window.innerHeight
    });
    const [isIconWidth, setIsIconWidth] = useState(windowSize.width * 0.05);
    const [isIconHeight, setIsIconHeight] = useState(windowSize.height * 0.09);
    const [isWagerBoxWidth, setIsWagerBoxWidth] = useState(windowSize.width * 0.07);
    const [isWagerBoxHeight, setIsWagerBoxHeight] = useState(windowSize.height * 0.09);
    const [isWagerTop, setIsWagerTop] = useState(windowSize.height * 0.154);
    const [isWagerMhaTop, setIsisWagerMhaTop] = useState(windowSize.height * 0.228);
    const [isGapY, setIsGapY] = useState(windowSize.height * 0.03);
    
    const playJackpotSound = () => {
        const audio = new Audio(jackpotSound);
        audio.play();
    }

    useEffect(() => {
        audioRef.current = new Audio(bgmusic);
        audioRef.current.loop = true;
        
        return () => {
            if (audioRef.current) {
                audioRef.current.pause();
                audioRef.current = null;
            }
        };
    }, []);

    useEffect(() => {
        if (audioRef.current) {
            if (isMusicOn) {
                audioRef.current.play().catch(error => {
                    console.error('Error playing audio:', error);
                });
            } else {
                audioRef.current.pause();
            }
        }
    }, [isMusicOn]);
    
    const toggleMusic = () => {
        setIsMusicOn(!isMusicOn);
    }

    return (
        <>
            {/* on Mobile */}
            <div className="flex mh-display-none md:hidden justify-between fixed bottom-[20%] px-[2px] w-full h-[8.48%]">
                <div className="w-[39.6%] flex justify-between">
                    <button className="w-[50%] h-full" onClick={toggleMusic} style={{ backgroundImage: `url(${isMusicOn ? music_on : music_off})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></button>
                    <button className="w-[50%] h-full scale-[1.4]" style={{ backgroundImage: `url(${myjp_icon})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></button>
                </div>

                <div className="w-[39.6%] flex justify-between">
                    <button className="w-[50%] h-full" style={{ backgroundImage: `url(${favorites})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></button>
                    <button className="w-[50%] h-full" style={{ backgroundImage: `url(${gear_normal})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></button>
                </div>
            </div>
            
            {/* on Desktop */}
            
            {/* over lg */}
            <button onClick={() => { dispatch(setIsBonusModal(true)) } } className='hidden mha-hidden lg:flex absolute right-0 z-[50] justify-center items-center' style={{ backgroundImage: `url(${dailyBox})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', width: `${isWagerBoxWidth}px`, height: `${isWagerBoxHeight}px`, top: `${isWagerTop}px` }}>
                <img src={goldbonusbg} alt="goldbonusbg" className="w-[80%] h-[80%]" />
                <img src={goldbonustitle} alt="goldbonustitle" className="absolute bottom-0 w-full h-[16%] px-[10%] mb-[8%]" />
            </button>
            {/* in mha area */}
            <button onClick={() => { dispatch(setIsBonusModal(true)) } } className='hidden mhaOut-hidden mha-display-show lg:flex absolute right-[1.67%] z-[50] justify-center items-center' style={{ backgroundImage: `url(${dailyBox})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', width: `${isIconWidth}px`, height: `${isIconHeight}px`, top: `${isWagerMhaTop}px` }}>
                <img src={goldbonusbg} alt="goldbonusbg" className="w-[80%] h-[80%]" />
                <img src={goldbonustitle} alt="goldbonustitle" className="absolute bottom-0 w-full h-[16%] px-[10%] mb-[8%]" />
            </button>
            {/* md to md */}
            <button onClick={() => { dispatch(setIsBonusModal(true)) } } className='hidden md:flex mha-hidden lg:hidden absolute right-0 z-[50] justify-center items-center' style={{ backgroundImage: `url(${dailyBox})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', width: `${isWagerBoxWidth}px`, height: `${isWagerBoxHeight}px`, top: `${isWagerMhaTop}px` }}>
                <img src={goldbonusbg} alt="goldbonusbg" className="w-[80%] h-[80%]" />
                <img src={goldbonustitle} alt="goldbonustitle" className="absolute bottom-0 w-full h-[16%] px-[10%] mb-[8%]" />
            </button>
            
            <div className="absolute hidden z-[20] w-full px-[1.67%] md:flex bottom-[20%] justify-between">
                <div className="flex flex-col" style={{gap: `${isGapY}px`}}>
                    <button className="w-[50%] h-full scale-[1.4]" style={{ backgroundImage: `url(${myjp_icon})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', width: `${isIconWidth}px`, height: `${isIconHeight}px` }}></button>
                    <button className="w-[50%] h-full" onClick={toggleMusic} style={{ backgroundImage: `url(${isMusicOn ? music_on : music_off})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', width: `${isIconWidth}px`, height: `${isIconHeight}px` }}></button>
                </div>
                
                <div className="flex flex-col" style={{ gap: `${isGapY}px` }}>
                    <button className="w-[50%] h-full" style={{ backgroundImage: `url(${favorites})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', width: `${isIconWidth}px`, height: `${isIconHeight}px` }}></button>
                    <button className="w-[50%] h-full" style={{ backgroundImage: `url(${gear_normal})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', width: `${isIconWidth}px`, height: `${isIconHeight}px` }}></button>
                </div>
            </div>
        </>    
    );
};

export default IconMenu;