import React, { useState, useEffect, useRef, useCallback } from 'react';
import mainBackground from '../assets/img/themes/bg_panoramic.jpg';

import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import useApi from '../hooks/useApi';
import { Navigation, Pagination, Mousewheel, Keyboard } from 'swiper/modules';
import { useSelector, useDispatch } from 'react-redux';
import { setGamePlayed, setGameList, setGameUrl, setGameSession, setPageSize, setCurrentPage, setIsTransitioning, setTotalPages } from '../store/reducers/gameSlice';
import { setIsBonusModal } from '../store/reducers/modal';
import { setLoading } from '../store/reducers/load';
import { setIsFirstLoad } from '../store/reducers/load';
// import WaitForImagesToLoad from '../helpers/WaitForImagesToLoad';
import IconMenu from './IconMenu';
import InfiniteScroll from 'react-infinite-scroll-component';

import logo from '../assets/img/themes/logo.png';
import Banner from './Banner';
import clickSound from '../assets/sounds/themes/vegasxwinter/click.mp3';
import slideSound from '../assets/sounds/themes/vegasxwinter/slide.mp3';
import wagerBox from '../assets/img/themes/wager_box.png';
import dailyBox from '../assets/img/themes/dailybox.png';
import goldbonusbg from '../assets/img/win/goldbonusbg.png';
import goldbonustitle from '../assets/img/win/goldbonustitle.png';
import frame from '../assets/img/themes/frame.png';
import leftArrow from '../assets/img/themes/leftarrow.png';
import rightArrow from '../assets/img/themes/rightarrow.png';
import GameModal from './GameModal';
import BonusModal from './BonusModal';

const MainContent = () => {
    const Api = useApi();
    const dispatch = useDispatch();

    const { user } = useSelector((store) => store.auth);
    const { gamePlayed, gameList: reduxGameList } = useSelector((state) => state.games);
    const isFirstLoad = useSelector(state => state.load.isFirstLoad);
    const isBonusModal = useSelector(state => state.modal.isBonusModal);

    const [error, setError] = useState(null);
    const [mobileGridItems, setMobileGridItems] = useState([]);
    const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
    const [slides, setSlides] = useState([]);
    const [loadingQueue, setLoadingQueue] = useState(new Set());
    const [swiperInstance, setSwiperInstance] = useState(null);
    const [mhSwiperTop, setMhSwiperTop] = useState(0);
    const [isInRange, setIsInRange] = useState(false);
    const [isInMiddleDesktopRange, setIsInMiddleDesktopRange] = useState(false);
    const [isLogoHeight, setIsLogoHeight] = useState(0);

    const [windowSize, setWindowSize] = useState({
        width: window.innerWidth,
        height: window.innerHeight
    });

    const [galleryImgheight, setGalleryImgheight] = useState(windowSize.height * 0.21);
    const [logoHeight, setLogoHeight] = useState(windowSize.height * 0.126);
    const [galleryGapH, setGalleryGapH] = useState(windowSize.height * 0.018);
    const [galleryGapW, setGalleryGapW] = useState(windowSize.width * 0.00885);
    const [swiperBtnH, setSwiperBtnH] = useState(windowSize.height * 0.13);

    const [TmpMt, setTmpMt] = useState(windowSize.height * 0.2227);
    const [wBoxTop, setwBoxTop] = useState(TmpMt - 48 - 5);

    const currentPage = useSelector(state => state.games.currentPage);
    const totalPages = useSelector(state => state.games.totalPages);
    const isTransitioning = useSelector(state => state.games.isTransitioning);
    const pageSize = useSelector(state => state.games.pageSize);
    const provider = useSelector(state => state.games.provider);
    const gameList = useSelector(state => state.games.gameList);
    const mobilePageSize = pageSize * 3;

    const effectRan = useRef(false);

    // Detect screen resize/orientation change
    useEffect(() => {
        const handleResize = () => {
            setWindowSize({
                width: window.innerWidth,
                height: window.innerHeight
            });
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('orientationchange', handleResize);
        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('orientationchange', handleResize);
        };
    }, []);

    // Recalculate dependent heights whenever windowSize changes
    useEffect(() => {
        setGalleryImgheight(windowSize.height * 0.21);
        setLogoHeight(windowSize.height * 0.126);
        setGalleryGapH(windowSize.height * 0.018);
        setGalleryGapW(windowSize.width * 0.00885);
        setSwiperBtnH(windowSize.height * 0.13);

        const newTmpMt = windowSize.height * 0.2227;
        setTmpMt(newTmpMt);
        setwBoxTop(newTmpMt - 48 - 5);
    }, [windowSize]);

    const handleGameClick = async (gameId, aggregator) => {
        // console.log(aggregator, "gameId")
        const tryTriggerGame = async () => {
            try {
                dispatch(setGamePlayed(true));
                const response = await Api.triggerGame(user.username, gameId, aggregator);
                // console.log(response, "response")
                if (response?.data?.result?.SessionUrl) {
                    const fullUrl = response.data.result.SessionUrl;
                    const session = response.data.result.SessionId;
                    dispatch(setGameSession(session))
                    dispatch(setGameUrl(fullUrl));
                } else {
                    throw new Error('Failed to get SessionUrl');
                }
            } catch (error) {
                console.error('Error triggering game:', error);
                console.error('Error details:', {
                    message: error.message,
                    response: error.response?.data,
                    status: error.response?.status
                });
                return error;
            }
        };

        let result = await tryTriggerGame();
        if (result instanceof Error) {
            // Try one more time if first attempt failed
            result = await tryTriggerGame();
        }
    };

    const playClickSound = () => {
        const audio = new Audio(clickSound);
        audio.play();
    }

    const playSlideSound = () => {
        const audio = new Audio(slideSound);
        audio.play();
    }

    const generateGridItems = (games = []) => {

        const items = games.map((game, index) =>
            <div
                key={`${game.code}_${index}` || index}
                className="relative h-[20vh] cursor-pointer hover:opacity-90 transition-opacity w-full touch-pan-y"
                // style={{ height: `${galleryImgheight}px` }}
                onClick={() => { handleGameClick(game.Id, game.aggregator); playClickSound(); }}
            >
                {/* , height: `${galleryImgheight}px` */}
                <div className="mh-main-img absolute w-full h-[20vh] inset-0 bg-cover bg-center bg-no-repeat rounded-[20px]" style={{ backgroundImage: `url(${game.aggregator === 'skyxspin' ? `https://admin.skyxspin.com/${game.Icon}` : `${process.env.REACT_APP_SERVER_URL}/thumbnails/225x140/${game.Id}.jpg`})` }}>
                    <img src={frame} alt="frame" className="w-full h-full object-fill" />
                </div>
            </div>);

        items.push(
            <div
                key="empty-child"
                className="relative h-[21vh]"
                style={{ minHeight: "200px" }}
            >
                <div className="absolute w-full inset-0">
                </div>
            </div>
        );

        return items;
    };


    const fetchGameList = async (provider, page, pageSize, isInitial = false, isScroll = false) => {
        try {
            if (loadingQueue.has(page) || isTransitioning) return;

            setLoadingQueue(prev => new Set([...prev, page]));

            dispatch(setLoading(true));

            const response = await Api.getGameList(provider, page, pageSize);

            if (response?.data?.result) {
                if (isScroll) {
                    // For infinite scroll, merge the new results with existing ones
                    dispatch(setGameList({
                        count: response.data.count,
                        result: [...(gameList?.result || []), ...response.data.result]
                    }));
                } else {
                    // For normal page navigation, replace the results
                    dispatch(setGameList(response.data));
                }
                dispatch(setCurrentPage(page));
                // await WaitForImagesToLoad(response.data.result);
            }
        } catch (error) {
            console.error('Fetch error:', error);
        } finally {
            setLoadingQueue(prev => {
                const newSet = new Set(prev);
                newSet.delete(page);
                return newSet;
            });
            dispatch(setLoading(false));
            dispatch(setIsTransitioning(false));

            if (isFirstLoad) {
                dispatch(setIsFirstLoad(false));
            }
        }
    };

    useEffect(() => {
        if (gameList && gameList.result) {
            // Update mobile grid items
            setMobileGridItems(generateGridItems(gameList.result));

            // Update slider content
            const newSlides = [{
                id: currentPage,
                content: (
                    <div className="mh-grid grid grid-cols-4 px-[6%] h-full mx-[30px] overflow-y-hidden"
                        style={{ columnGap: `${galleryGapW}px`, rowGap: `${galleryGapH}px` }}
                    >
                        {generateGridItems(gameList.result)}
                    </div>
                )
            }];

            setSlides(newSlides);
            dispatch(setTotalPages(Math.ceil(gameList.count / pageSize)));

            // Force Swiper reinitialization if needed
            if (swiperInstance) {
                setTimeout(() => {
                    swiperInstance.update();
                    swiperInstance.slideToLoop(0, 0);
                }, 100);
            }
        }
    }, [gameList, currentPage, pageSize, swiperInstance]);

    const handleNavigation = async (direction) => {
        if (isTransitioning) return;

        dispatch(setIsTransitioning(true));
        playSlideSound();

        const newPage = direction === 'next'
            ? (currentPage % totalPages) + 1
            : (currentPage - 2 + totalPages) % totalPages + 1;

        await fetchGameList(provider, newPage, pageSize);
    };

    const swiperParams = {
        cssMode: true,
        loop: false,
        slidesPerView: 1,
        loopAdditionalSlides: 2,
        speed: 500,
        navigation: true,
        modules: [Navigation, Pagination, Mousewheel, Keyboard],
        on: {
            init: (swiper) => {
                setSwiperInstance(swiper);
                setTimeout(() => {
                    const prevBtn = document.querySelector('.swiper-button-prev');
                    const nextBtn = document.querySelector('.swiper-button-next');
                    if (prevBtn) prevBtn.style.display = 'flex';
                    if (nextBtn) nextBtn.style.display = 'flex';
                }, 100);
            }
        }
    };

////////////////////////////////////////////////////////////
    // caculate swiper img margin top
    useEffect(() => {
        const handleResize = () => {
            setWindowSize({
                width: window.innerWidth,
                height: window.innerHeight
            });
            setIsMobile(window.innerWidth < 768); // Update isMobile reactively
            setMhSwiperTop(window.innerHeight * 0.04); // Also update swiper top
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        const firstRangeMediaQuery = window.matchMedia(
            '(min-width: 600px) and (max-width: 1024px) and (min-height: 250px) and (max-height: 500px)'
        );

        const middleDesktopMediaQuery = window.matchMedia(
            '(min-width: 768px) and (max-width: 1024px) and (min-height: 501px) and (max-height: 900px)'
        );

        const handleFirstRangeChange = (e) => {
            setIsInRange(e.matches);
            // setMhSwiperTop(window.innerHeight * 0.04);
        };

        const handleMiddleDesktopChange = (e) => {
            setIsInMiddleDesktopRange(e.matches);
            setMhSwiperTop(window.innerHeight * 0.04);
        };

        firstRangeMediaQuery.addEventListener('change', handleFirstRangeChange);
        middleDesktopMediaQuery.addEventListener('change', handleMiddleDesktopChange);

        handleFirstRangeChange(firstRangeMediaQuery);
        handleMiddleDesktopChange(middleDesktopMediaQuery);

        return () => {
            firstRangeMediaQuery.removeEventListener('change', handleFirstRangeChange);
            middleDesktopMediaQuery.removeEventListener('change', handleMiddleDesktopChange);
        };
    }, []);
////////////////////////////////////////////////////////////

    useEffect(() => {
        if (reduxGameList && reduxGameList.result) {
            setMobileGridItems(generateGridItems(reduxGameList.result));
        }
    }, [reduxGameList]);

    // Update effect for initial load
    useEffect(() => {

        fetchGameList(provider, 1, pageSize, true);
    }, []);

    return (
        <main className="relative flex flex-col w-full h-full mh-main-content lg:min-h-[calc(100dvh-62px)] overflow-hidden touch-none">
            {gamePlayed && (
                <GameModal />
            )}
            {isBonusModal && (
                <BonusModal />
            )}
            
            <div
                className="absolute inset-0 w-full h-full animate-zoomEffect touch-none"
                style={{
                    backgroundImage: `url(${mainBackground})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    backgroundRepeat: 'no-repeat'
                }}
            />

            {/* Wager Box on Mobile only */}
            <div className='absolute left-[21.6%] flex mh-display-none md:hidden justify-center items-center w-[56.8%] h-[3rem] self-end' style={{ backgroundImage: `url(${wagerBox})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', top: `${wBoxTop}px` }}>
                <p className="text-center text-white text-[0.625rem] font-['Impact'] leading-[1.1] tracking-[0.4rem]" style={{ textShadow: '2px 2px 3px rgba(0,0,0,1)', letterSpacing: '0.05em' }}>
                    BALANCE 8056 CHARGEABLE BALANCE 2028
                    <br />
                    WAGER GOOD CASHBACK BONUS 1560
                    <br />
                    DAILY BONUS 28
                </p>
            </div>

            {/* Gold Bonus Button on Mobile only */}
            <button onClick={() => { dispatch(setIsBonusModal(true)) } } className='absolute right-[10px] flex md:hidden justify-center items-center w-[2.75rem] h-[2.75rem] self-end' style={{ backgroundImage: `url(${dailyBox})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', top: `${wBoxTop + 2}px` }}>
                <img src={goldbonusbg} alt="goldbonusbg" className="w-[2rem] h-[2rem]" />
                <img src={goldbonustitle} alt="goldbonustitle" className="absolute bottom-0 w-full h-[8px] px-[4px] mb-[2px]" />
            </button>

            <div className="z-10 h-auto md:mt-0">
                <Banner className="hidden mha-hidden lg:flex" />
                <div className="hidden mh-display-show md:flex md:flex-col w-full items-center justify-center">
                    <img src={logo} alt="logo" className="w-[42%] mha-logo-w mha-logo-mt mt-[-10px] mh-logo mh-logo-mt" style={{ height: `${logoHeight}px` }} />
                </div>
                <Banner className="hidden mha-display-show mh-display-show md:flex lg:hidden" />
            </div>

            <div className="hidden mh-display-show mh-swiper-H md:block pt-[10px] h-screen md:h-[47dvh]" style={(isInRange || isInMiddleDesktopRange) ? { marginTop: `${mhSwiperTop}px` } : {}}>
                <div className="relative w-full h-full">
                    <Swiper
                        {...swiperParams}
                        cssMode={true}
                        mousewheel={true}
                        keyboard={true}
                        className="mySwiper h-full"
                    >
                        {slides.map(slide => (
                            <SwiperSlide key={slide.id}>
                                {slide.content}
                            </SwiperSlide>
                        ))}
                        <div
                            className="mh-swiper-btn swiper-button-prev !flex !items-center !justify-center !w-[7%] !bg-contain !bg-no-repeat !bg-center"
                            onClick={() => handleNavigation('prev')}
                            style={{
                                backgroundImage: `url(${leftArrow})`,
                                left: '0',
                                display: 'flex',
                                top: '45%',
                                display: 'flex',
                                position: 'absolute',
                                height: `${swiperBtnH}px`,
                            }}
                        />
                        <div
                            className="mh-swiper-btn swiper-button-next !flex !items-center !justify-center !w-[7%] !bg-contain !bg-no-repeat !bg-center"
                            onClick={() => handleNavigation('next')}
                            style={{
                                backgroundImage: `url(${rightArrow})`,
                                right: '0',
                                display: 'flex',
                                top: '45%',
                                display: 'flex',
                                position: 'absolute',
                                height: `${swiperBtnH}px`,
                            }}
                        />
                    </Swiper>
                </div>
            </div>

            <div className='flex flex-col mh-display-none md:hidden px-[13.5%] h-[calc(100vh-200px)] overflow-y-auto overflow-hidden'
                id="scrollableDiv"
                style={{
                    transform: 'translateZ(0)',
                    contain: 'content',
                    ...(isMobile ? {
                        marginTop: `${TmpMt}px`
                    } : {})
                }}
            >
                <InfiniteScroll
                    dataLength={gameList?.result?.length || 0}
                    next={() => fetchGameList(provider, currentPage + 1, mobilePageSize, false, true)}
                    hasMore={gameList?.count > (gameList?.result?.length || 0)}
                    loader={
                        <div className="flex justify-center items-center py-4">
                            <div className="w-8 h-8 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
                        </div>
                    }
                    scrollableTarget="scrollableDiv"
                    endMessage={
                        <div className="text-center text-white py-4">
                            No more games to load
                        </div>
                    }
                >
                    <div className="grid grid-cols-1 gap-8">
                        {mobileGridItems}
                    </div>
                </InfiniteScroll>
            </div>

            <IconMenu />
        </main >
    );
};

export default MainContent;